#!/sbin/openrc-run
extra_stopped_commands="setup"

retry="60"
pidfile="/run/mysqld/$RC_SVCNAME.pid"
command="/usr/bin/mysqld_safe"
command_args="--syslog --nowatch --pid-file=$pidfile"

depend() {
	use net
	need localmount
}

start_pre() {
	required_dirs=$(getconf datadir "/var/lib/mysql")

	if [ ! -d $required_dirs/mysql ]; then
		eerror "Datadir '$required_dirs' is empty or invalid."
		eerror "Run '/etc/init.d/mariadb setup' to create new database."
	fi
}

start_post() {
	ewaitfile 10 $(getconf socket "/run/mysqld/mysqld.sock")
}

setup() {
	ebegin "Creating a new MySQL database"
	mysql_install_db --user=mysql --datadir=/var/lib/mysql
	eend $?
}

getconf() {
	v=$(my_print_defaults --mysqld | grep ^--$1)
	[ -z $v ] && echo $2 || echo ${v#*=}
}

command:
MYSQL_PWD=$(cat /root/.mysql_root_pw) mariadb -uroot -e "
CREATE DATABASE IF NOT EXISTS appdata;
USE appdata;
CREATE TABLE IF NOT EXISTS orders (id INT AUTO_INCREMENT PRIMARY KEY, note VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO orders (note) VALUES ('seed-order-1'), ('seed-order-2'), ('seed-order-3');
SELECT * FROM orders;
"

